// 윌앤비전 - 위험성평가

// ── 회사별 공정 정의 ──
const RISK_COMPANIES = {
  "윌앤비전 FM사업본부":  ["시설관리", "미화", "보안", "주차관리", "안내", "사무행정", "출퇴근"],
  // FM사업부문 - 공항사업본부 — 공정 정보는 추후 사용자가 알려주면 추가
  "공항사업본부":         ["사무행정", "출퇴근"],
  "윌앤비전 HR사업본부":  ["식기세척", "판매직", "주차관리", "사무행정", "출퇴근"],
  "윌앤비전 CRM사업본부": ["사무실", "고객상담", "사무행정", "출퇴근"],
  "KBCI":           ["입출고·창고관리", "지게차 운영", "피킹·포장", "사무행정", "출퇴근"],
  "동부캐리어":     ["자동차 출고·운송", "사무행정", "출퇴근"],
  "윌비모터스":    ["차량 수리·진단", "판금·도장", "휠 복원", "차량 세차", "사무행정", "출퇴근"],
};
const RISK_COMPANY_LIST = Object.keys(RISK_COMPANIES);
const RISK_COMPANY_KEY = "wv_risk_company";

// ── 회사명 마이그레이션: 본부 → 사업본부 (한 번만 자동 실행) ──
(function migrateBonbu() {
  try {
    const MIGRATION_KEY = "wv_risk_migration_v2_사업본부";
    if (typeof localStorage === "undefined") return;
    if (localStorage.getItem(MIGRATION_KEY) === "done") return;

    const mapping = {
      "윌앤비전 FM본부":  "윌앤비전 FM사업본부",
      "윌앤비전 HR본부":  "윌앤비전 HR사업본부",
      "윌앤비전 CRM본부": "윌앤비전 CRM사업본부",
    };
    const slugOld = (s) => s.replace(/\s/g, "_");

    // 1. wv_risk_company (구버전 호환 단일 회사 키)
    const oldCo = localStorage.getItem(RISK_COMPANY_KEY);
    if (oldCo && mapping[oldCo]) {
      localStorage.setItem(RISK_COMPANY_KEY, mapping[oldCo]);
    }

    // 2. evalContext (현재 평가 컨텍스트)
    const ctxRaw = localStorage.getItem("wv_risk_evalContext");
    if (ctxRaw) {
      try {
        const ctx = JSON.parse(ctxRaw);
        if (ctx?.company && mapping[ctx.company]) {
          const oldName = ctx.company;
          const newName = mapping[oldName];
          const oldEvalId = ctx.evalId;
          const newEvalId = oldEvalId.replace(slugOld(oldName), slugOld(newName));
          ctx.company = newName;
          ctx.evalId = newEvalId;
          localStorage.setItem("wv_risk_evalContext", JSON.stringify(ctx));
        }
      } catch (e) {}
    }

    // 3. evalList + 각 평가의 STEP 데이터 (cover/site/meeting/photos/training/mtgphotos + table_{type})
    const listRaw = localStorage.getItem("wv_risk_evalList");
    if (listRaw) {
      try {
        const list = JSON.parse(listRaw);
        const updated = list.map(e => {
          if (e?.company && mapping[e.company]) {
            const oldName = e.company;
            const newName = mapping[oldName];
            const oldEvalId = e.evalId;
            const newEvalId = oldEvalId.replace(slugOld(oldName), slugOld(newName));

            // 5개 STEP 키 + mtgphotos 이동
            ["cover", "site", "meeting", "photos", "training", "mtgphotos"].forEach(step => {
              const oldKey = `wv_risk_${step}_${oldEvalId}`;
              const data = localStorage.getItem(oldKey);
              if (data) {
                localStorage.setItem(`wv_risk_${step}_${newEvalId}`, data);
                localStorage.removeItem(oldKey);
              }
            });

            // 위험성평가표 (공정별 — 모든 키 스캔)
            const prefix = `wv_risk_table_${oldEvalId}_`;
            const allKeys = Object.keys(localStorage);
            allKeys.forEach(k => {
              if (k.startsWith(prefix)) {
                const tableType = k.substring(prefix.length);
                const data = localStorage.getItem(k);
                if (data) {
                  localStorage.setItem(`wv_risk_table_${newEvalId}_${tableType}`, data);
                  localStorage.removeItem(k);
                }
              }
            });

            return { ...e, company: newName, evalId: newEvalId };
          }
          return e;
        });
        localStorage.setItem("wv_risk_evalList", JSON.stringify(updated));
      } catch (e) {}
    }

    // 4. 결재 대기 목록(pending approvals)의 company 필드도 변경
    const pendingRaw = localStorage.getItem("wv_risk_pending_approvals");
    if (pendingRaw) {
      try {
        const pending = JSON.parse(pendingRaw);
        const updated = pending.map(p => {
          if (p?.company && mapping[p.company]) {
            return { ...p, company: mapping[p.company] };
          }
          return p;
        });
        localStorage.setItem("wv_risk_pending_approvals", JSON.stringify(updated));
      } catch (e) {}
    }

    localStorage.setItem(MIGRATION_KEY, "done");
    console.log("[Migration] 본부 → 사업본부 마이그레이션 완료");
  } catch (e) {
    console.warn("[Migration] 본부 마이그레이션 실패:", e);
  }
})();

// ── 위험성평가 종류 ──
const RISK_EVAL_TYPES = [
  { id: "initial",    label: "최초 위험성평가", icon: "file",       color: "#1e5fcf",
    desc: "사업 개시 후 1개월 이내 착수",
    bg: "#eff6ff", bgActive: "#dbeafe" },
  { id: "regular",    label: "정기 위험성평가", icon: "chart",      color: "#16a34a",
    desc: "매년 1회",
    bg: "#f0fdf4", bgActive: "#dcfce7" },
  { id: "occasional", label: "수시 위험성평가", icon: "alert",      color: "#d97706",
    desc: "위험성평가 대상 작업 추가, 사고 발생 시",
    bg: "#fffbeb", bgActive: "#fef3c7" },
];
const RISK_EVAL_CTX_KEY = "wv_risk_evalContext";
const RISK_EVAL_LIST_KEY = "wv_risk_evalList";

// 평가 컨텍스트 헬퍼
const getEvalContext = () => riskLoad(RISK_EVAL_CTX_KEY);
const setEvalContext = (ctx) => riskSave(RISK_EVAL_CTX_KEY, ctx);
const clearEvalContext = () => { try { localStorage.removeItem(RISK_EVAL_CTX_KEY); } catch(e) {} };
const getEvalList = () => riskLoad(RISK_EVAL_LIST_KEY) || [];
const saveEvalList = (list) => riskSave(RISK_EVAL_LIST_KEY, list);

// 평가 ID 생성: initial/regular는 본부(+사업장)+연도, occasional은 본부(+사업장)+날짜
// 사업장명이 있으면 충돌 방지를 위해 ID에 포함
const generateEvalId = (type, company, year, date, 사업장명) => {
  const slug = (company || "").replace(/\s/g, "_");
  const siteSlug = 사업장명 ? `_${사업장명.replace(/[\s\/\\]/g, "_")}` : "";
  if (type === "occasional") return `occasional_${slug}${siteSlug}_${date}`;
  return `${type}_${slug}${siteSlug}_${year}`;
};

// 새 평가 등록 + 컨텍스트 설정
const addEvaluation = ({ type, company, year, date, 사유, 사업장명 }) => {
  const evalId = generateEvalId(type, company, year, date, 사업장명);
  const ctx = { evalId, type, company, year, date, 사유: 사유 || "", 사업장명: 사업장명 || "", createdAt: new Date().toISOString() };
  const list = getEvalList();
  if (!list.find(e => e.evalId === evalId)) list.push(ctx);
  saveEvalList(list);
  setEvalContext(ctx);
  return ctx;
};

// 평가의 표시용 사업장명 조회 (evalContext에 없으면 표지에서 조회)
const getEvalSiteName = (evalContext) => {
  if (!evalContext) return "";
  if (evalContext.사업장명) return evalContext.사업장명;
  const coverForm = riskLoad(`wv_risk_cover_${evalContext.evalId}`)?.form;
  return coverForm?.사업장명 || "";
};

// 평가 삭제 + 관련 모든 STEP 데이터 삭제
const deleteEvaluation = (evalId) => {
  const list = getEvalList().filter(e => e.evalId !== evalId);
  saveEvalList(list);
  // 관련 키 모두 제거
  ["cover", "site", "meeting", "photos", "training"].forEach(step => {
    try { localStorage.removeItem(`wv_risk_${step}_${evalId}`); } catch(e) {}
  });
  // 위험성평가표 (모든 공정)
  Object.values(RISK_COMPANIES).flat().forEach(tt => {
    try { localStorage.removeItem(`wv_risk_table_${evalId}_${tt}`); } catch(e) {}
  });
};

// 평가 복제 (작년 데이터 → 새 평가로 복사)
const cloneEvaluation = (sourceEvalId, newCtx) => {
  const newEvalId = newCtx.evalId;
  ["cover", "site", "meeting", "photos", "training"].forEach(step => {
    const data = riskLoad(`wv_risk_${step}_${sourceEvalId}`);
    if (data) riskSave(`wv_risk_${step}_${newEvalId}`, data);
  });
  const allTypes = RISK_COMPANIES[newCtx.company] || [];
  allTypes.forEach(tableType => {
    const data = riskLoad(`wv_risk_table_${sourceEvalId}_${tableType}`);
    if (data) riskSave(`wv_risk_table_${newEvalId}_${tableType}`, data);
  });
};

// 평가의 진행 상태 계산 (6단계 기준: 표지/사업장정보/회의록/위험성평가표/사진대지/결과교육)
const getEvalProgress = (evalId) => {
  const ctx = getEvalList().find(e => e.evalId === evalId);
  const allTypes = ctx ? (RISK_COMPANIES[ctx.company] || []) : [];
  const savedTables = allTypes.filter(t => !!riskLoad(`wv_risk_table_${evalId}_${t}`));
  // STEP 4(위험성평가표)는 "모든 공정 저장 시" 1단계 완료로 카운트
  const tableStepDone = allTypes.length > 0 && savedTables.length === allTypes.length;
  // 6단계 각각 완료 여부
  const stepStatus = [
    !!riskLoad(`wv_risk_cover_${evalId}`),     // STEP 1: 표지
    !!riskLoad(`wv_risk_site_${evalId}`),      // STEP 2: 사업장 정보
    !!riskLoad(`wv_risk_meeting_${evalId}`),   // STEP 3: 회의록
    tableStepDone,                              // STEP 4: 위험성평가표 (전체 공정)
    !!riskLoad(`wv_risk_photos_${evalId}`),    // STEP 5: 사진대지
    !!riskLoad(`wv_risk_training_${evalId}`),  // STEP 6: 결과 전파교육
  ];
  const doneCount = stepStatus.filter(Boolean).length;
  return {
    steps: doneCount,
    totalSteps: 6,
    tables: savedTables.length,
    totalTables: allTypes.length,
    allDone: doneCount === 6,
  };
};

// ── 결재 요청 / 전송 관련 헬퍼 ──
const RISK_PENDING_KEY = "wv_risk_pending_approvals";

// 평가가 결재 요청에 필요한 모든 데이터를 갖추었는지 확인
// 반환: { ok: boolean, missing: string[], coverForm: object|null }
const checkRiskSubmittable = (evalId) => {
  if (!evalId) return { ok: false, missing: ["평가 컨텍스트 없음"], coverForm: null };
  const progress = getEvalProgress(evalId);
  const missing = [];
  const STEP_LABELS = { cover: "표지", site: "사업장 정보", meeting: "회의록", photos: "개선결과 사진대지", training: "결과 전파교육" };
  ["cover", "site", "meeting", "photos", "training"].forEach(s => {
    if (!riskLoad(`wv_risk_${s}_${evalId}`)) missing.push(STEP_LABELS[s]);
  });
  if (progress.totalTables > 0 && progress.tables < progress.totalTables) {
    missing.push(`위험성평가표 (${progress.totalTables - progress.tables}개 공정 미작성)`);
  }
  const coverForm = riskLoad(`wv_risk_cover_${evalId}`)?.form || null;
  if (coverForm) {
    if (!coverForm.사업장명) missing.push("표지: 사업장명");
    if (!coverForm.평가기간_시작 || !coverForm.평가기간_종료) missing.push("표지: 평가기간");
    if (!coverForm.관리감독자_성명) missing.push("표지: 관리감독자 성명");
    // 서명은 종이 인쇄 후 직접 작성 — 디지털 서명 패드 제거됨
  }
  return { ok: missing.length === 0, missing, coverForm };
};

// 이미 결재 요청이 전송되었는지 확인
const getRiskSubmissionStatus = (evalId) => {
  const coverData = riskLoad(`wv_risk_cover_${evalId}`);
  const form = coverData?.form;
  if (form?.상태 === "전송됨") {
    return { sent: true, at: form.전송일시 || "", by: form.관리감독자_성명 || "" };
  }
  return { sent: false, at: "", by: "" };
};

// 결재 요청 전송 (표지 상태 업데이트 + pending approvals에 등록)
// 반환: { ok: boolean, at: string, error?: string }
const submitRiskForApproval = (ctx) => {
  if (!ctx?.evalId) return { ok: false, error: "평가 컨텍스트 없음", at: "" };
  const { ok, missing, coverForm } = checkRiskSubmittable(ctx.evalId);
  if (!ok) return { ok: false, error: `다음 항목을 먼저 완료해주세요:\n\n• ${missing.join("\n• ")}`, at: "" };
  const status = getRiskSubmissionStatus(ctx.evalId);
  if (status.sent) return { ok: false, error: `이미 ${status.at}에 전송된 평가입니다.`, at: status.at };

  const now = new Date();
  const at = now.toLocaleString("ko-KR");
  const tStr = now.toLocaleTimeString("ko-KR", { hour: "2-digit", minute: "2-digit" });
  // 표지 상태 업데이트
  const updatedCover = { ...coverForm, 상태: "전송됨", 전송일시: at };
  riskSave(`wv_risk_cover_${ctx.evalId}`, { form: updatedCover, _savedAt: tStr });
  // 결재 대기 목록에 등록
  const pending = riskLoad(RISK_PENDING_KEY) || [];
  const typeLabel = RISK_EVAL_TYPES.find(t => t.id === ctx.type)?.label || "위험성평가";
  pending.push({
    id: Date.now(),
    evalId: ctx.evalId,
    company: ctx.company,
    docType: `${typeLabel} (${ctx.type === "occasional" ? ctx.date : ctx.year + "년"})`,
    site: coverForm.사업장명,
    period: `${coverForm.평가기간_시작} ~ ${coverForm.평가기간_종료}`,
    submittedBy: coverForm.관리감독자_성명,
    submittedAt: at,
    status: "검토대기",
    targetRoles: ["safety", "admin"],
  });
  localStorage.setItem(RISK_PENDING_KEY, JSON.stringify(pending));
  return { ok: true, at };
};

