// 헬퍼: 세부작업에 허용된 위험분류 목록
const getAllowedHazardCats = (task) => {
  if (!task || !TASK_HAZARD_DETAIL[task]) return HAZARD_CATS;
  return Object.keys(TASK_HAZARD_DETAIL[task]);
};
// 헬퍼: 세부작업+위험분류에 허용된 원인 목록
const getAllowedHazardCauses = (task, cat) => {
  if (!cat) return [];
  const detail = TASK_HAZARD_DETAIL[task];
  if (!detail || !detail[cat]) return HAZARD_DROPDOWN[cat] || [];
  return detail[cat];
};
// 하위 호환 (이전 이름)
const TASK_HAZARD_CATEGORIES = TASK_HAZARD_DETAIL;

