// 헬퍼: 세부작업 + 원인 → 예상재해 (없으면 빈 문자열)
const getAutoAccident = (task, cause) => {
  if (!task || !cause) return "";
  return TASK_CAUSE_ACCIDENT[task]?.[cause] || "";
};

// ── 매핑 자동 검증 (개발용) ──
// 콘솔에서 validateRiskMappings() 호출하면 누락/불일치 케이스 출력
window.validateRiskMappings = () => {
  const issues = { missingAccident: [], deadAccident: [], missingDetail: [], summary: {} };
  // 1) DETAIL에는 있는데 ACCIDENT에는 없는 원인 (예상재해 자동 채움 안됨)
  Object.entries(TASK_HAZARD_DETAIL).forEach(([task, cats]) => {
    const allCauses = new Set();
    Object.values(cats).forEach(causes => causes.forEach(c => allCauses.add(c)));
    allCauses.forEach(cause => {
      if (!TASK_CAUSE_ACCIDENT[task]?.[cause]) {
        issues.missingAccident.push({ task, cause });
      }
    });
  });
  // 2) ACCIDENT에는 있는데 DETAIL에는 없는 원인 (선택 불가능한 매핑 = 죽은 데이터)
  Object.entries(TASK_CAUSE_ACCIDENT).forEach(([task, causeMap]) => {
    const detailCauses = new Set();
    if (TASK_HAZARD_DETAIL[task]) {
      Object.values(TASK_HAZARD_DETAIL[task]).forEach(causes => causes.forEach(c => detailCauses.add(c)));
    }
    Object.keys(causeMap).forEach(cause => {
      if (!detailCauses.has(cause)) {
        issues.deadAccident.push({ task, cause });
      }
    });
  });
  // 3) WORK_TASKS에는 있는데 TASK_HAZARD_DETAIL에는 매핑 없는 세부작업
  Object.entries(WORK_TASKS).forEach(([proc, tasks]) => {
    tasks.forEach(task => {
      if (task === "기타" || task === "기타 보수 작업") return; // 의도된 미정의
      if (!TASK_HAZARD_DETAIL[task]) {
        issues.missingDetail.push({ process: proc, task });
      }
    });
  });
  // 요약
  issues.summary = {
    "예상재해 매핑 누락 (DETAIL → ACCIDENT 없음)": issues.missingAccident.length,
    "죽은 매핑 (ACCIDENT만 있고 DETAIL 없음)": issues.deadAccident.length,
    "필터 매핑 누락 (WORK_TASKS → DETAIL 없음)": issues.missingDetail.length,
  };
  console.group("🔍 위험성평가 매핑 검증 결과");
  console.table(issues.summary);
  if (issues.missingAccident.length) {
    console.warn("[1] 예상재해 자동 채움 안됨:");
    console.table(issues.missingAccident);
  }
  if (issues.deadAccident.length) {
    console.warn("[2] 사용 안되는 죽은 매핑:");
    console.table(issues.deadAccident);
  }
  if (issues.missingDetail.length) {
    console.warn("[3] 위험분류 필터 안되는 세부작업:");
    console.table(issues.missingDetail);
  }
  if (!issues.missingAccident.length && !issues.deadAccident.length && !issues.missingDetail.length) {
    console.log("✅ 모든 매핑이 정상입니다!");
  }
  console.groupEnd();
  return issues;
};

