// ── 재해유형 ──
const ACCIDENT_TYPES = [
  "떨어짐","넘어짐","깔림·뒤집힘","부딪힘·접촉","끼임","맞음","무너짐",
  "불균형 및 무리한 동작","이상온도 접촉","화학물질 누출·접촉","산소결핍",
  "화재","폭발·파열","감전","폭력행위","절단·베임·찔림","빠짐·익사",
  "사업장내 교통사고","사업장외 교통사고","기타",
];

// ── 추정기준 3×3 ──
const RISK_POSSIBLE = ["상(3)", "중(2)", "하(1)"];
const RISK_SEVERITY = ["대(3)", "중(2)", "소(1)"];
const RISK_MATRIX = {
  "상(3)": { "대(3)": 9, "중(2)": 6, "소(1)": 3 },
  "중(2)": { "대(3)": 6, "중(2)": 4, "소(1)": 2 },
  "하(1)": { "대(3)": 3, "중(2)": 2, "소(1)": 1 },
};
function getRiskLevel(p, s) {
  const score = RISK_MATRIX[p]?.[s] || 0;
  if (score >= 6) return { score, label: "높음", color: "#dc2626", mgmt: "즉시 개선 필요" };
  if (score >= 3) return { score, label: "보통", color: "#d97706", mgmt: "개선" };
  if (score >= 1) return { score, label: "낮음", color: "#059669", mgmt: "현재 상태 유지" };
  return { score: 0, label: "-", color: "var(--fg-3)", mgmt: "" };
}

